import { useEffect, useMemo, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import SingleResult from '../components/SingleResult'
import { subscribeResult, cancelResult } from '../resultStore'

function bandOf(pct) {
  if (pct >= 65) return 'Malicious'
  if (pct >= 45) return 'Suspicious'
  if (pct >= 40) return 'Borderline'
  return 'Not-suspicious'
}

const BAND_COLOR = {
  'Malicious':     'var(--danger)',
  'Suspicious':    'var(--warning)',
  'Borderline':    'var(--caution)',
  'Not-suspicious':'var(--success)',
}
const BAND_DIM = {
  'Malicious':     'var(--danger-dim)',
  'Suspicious':    'var(--warning-dim)',
  'Borderline':    'var(--caution-dim)',
  'Not-suspicious':'var(--success-dim)',
}
const BAND_ICON = {
  'Malicious':     '🚨',
  'Suspicious':    '🔍',
  'Borderline':    '⚠️',
  'Not-suspicious':'✅',
}

const FILTERS = [
  { key: 'all',            label: 'All' },
  { key: 'Malicious',      label: 'Malicious' },
  { key: 'Suspicious',     label: 'Suspicious' },
  { key: 'Borderline',     label: 'Borderline' },
  { key: 'Not-suspicious', label: 'Not-suspicious' },
]

export default function ResultPage() {
  const { state } = useLocation()
  const navigate  = useNavigate()
  const [filter, setFilter]                 = useState('all')
  const [pageSize, setPageSize]             = useState(200)
  const [streamedResult, setStreamedResult] = useState(null)
  const [streamError, setStreamError]       = useState(null)

  // Streaming mode: subscribe to the result published by HomePage after navigating early
  useEffect(() => {
    if (!state?.streaming) return
    subscribeResult(data => {
      if (data._streamError) setStreamError(data._streamError)
      else setStreamedResult(data)
    })
    return () => cancelResult()
  }, [state?.streaming])

  // Restore scroll position after returning from user detail page
  useEffect(() => {
    const savedY = sessionStorage.getItem('resultScrollY')
    if (savedY) {
      window.scrollTo(0, parseInt(savedY, 10))
      sessionStorage.removeItem('resultScrollY')
    }
  }, [])

  useEffect(() => {
    if (!state?.result && !state?.streaming) navigate('/')
  }, [state, navigate])

  const result = streamedResult ?? state?.result

  // ── Memoised derived state — only recomputes when result or filter changes ──
  const annotated = useMemo(() => {
    if (!Array.isArray(result?.results)) return []
    return result.results.map(r => ({ ...r, band: bandOf(parseFloat((r.probability * 100).toFixed(1))) }))
  }, [result])

  const counts = useMemo(() => {
    const c = { all: annotated.length }
    annotated.forEach(r => { c[r.band] = (c[r.band] ?? 0) + 1 })
    return c
  }, [annotated])

  const filtered = useMemo(() => {
    return filter === 'all' ? annotated : annotated.filter(r => r.band === filter)
  }, [annotated, filter])

  // ── Streaming loading skeleton ────────────────────────────────────────────
  if (state?.streaming && !result && !streamError) {
    return (
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/')}>← Back to Analysis</button>
          <span style={{ color: 'var(--text-muted)', fontSize: '0.875rem' }}>Processing batch analysis…</span>
        </div>
        <div className="card" style={{ padding: '3rem', textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', marginBottom: '0.75rem' }}>⏳</div>
          <p style={{ color: 'var(--text-dim)', fontWeight: 600, marginBottom: '0.35rem' }}>Analysing records…</p>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>Results will appear automatically when ready.</p>
        </div>
      </div>
    )
  }

  // ── Stream error ──────────────────────────────────────────────────────────
  if (streamError) {
    return (
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/')}>← Back to Analysis</button>
        </div>
        <div className="card" style={{ padding: '2rem', textAlign: 'center', borderColor: 'var(--danger)' }}>
          <p style={{ color: 'var(--danger)', fontWeight: 600, marginBottom: '0.5rem' }}>Analysis failed</p>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.875rem' }}>{streamError}</p>
        </div>
      </div>
    )
  }

  if (!result) return null

  // ── Batch CSV mode ────────────────────────────────────────────────────────
  if (Array.isArray(result.results)) {
    const visible = filtered.slice(0, pageSize)
    const hasMore = filtered.length > pageSize

    function handleRowClick(r) {
      sessionStorage.setItem('resultScrollY', String(window.scrollY))
      navigate('/result/user', { state: { row: r, from: state } })
    }

    return (
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/')}>
            ← Back to Analysis
          </button>
          <span style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
            CSV Batch &mdash; <strong style={{ color: 'var(--text-dim)' }}>{result.total_records ?? annotated.length}</strong> scanned
            &nbsp;&middot;&nbsp;
            <strong style={{ color: 'var(--danger)' }}>{counts['Malicious'] ?? 0}</strong> malicious
            &nbsp;&middot;&nbsp;
            <strong style={{ color: 'var(--warning)' }}>{counts['Suspicious'] ?? 0}</strong> suspicious
            &nbsp;&middot;&nbsp;
            <strong style={{ color: 'var(--caution)' }}>{counts['Borderline'] ?? 0}</strong> borderline
            &nbsp;&middot;&nbsp;
            <strong style={{ color: 'var(--text-dim)' }}>
              {(counts['Malicious'] ?? 0) + (counts['Suspicious'] ?? 0) + (counts['Borderline'] ?? 0)}
            </strong> total at-risk
            {result.saved_at && (
              <span style={{ marginLeft: '0.75rem', opacity: 0.5, fontSize: '0.75rem' }}>
                saved {new Date(result.saved_at).toLocaleString()}
              </span>
            )}
          </span>
        </div>

        {/* ── Filter bar ── */}
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '1rem' }}>
          {FILTERS.map(f => {
            const active = filter === f.key
            const col    = f.key === 'all' ? 'var(--text-dim)' : BAND_COLOR[f.key]
            const dim    = f.key === 'all' ? 'rgba(255,255,255,0.07)' : BAND_DIM[f.key]
            const icon   = f.key === 'all' ? '' : BAND_ICON[f.key] + ' '
            return (
              <button
                key={f.key}
                onClick={() => setFilter(f.key)}
                style={{
                  padding: '0.35rem 0.85rem',
                  borderRadius: '99px',
                  border: active ? `1.5px solid ${col}` : '1.5px solid var(--border)',
                  background: active ? dim : 'transparent',
                  color: active ? col : 'var(--text-muted)',
                  fontWeight: active ? 700 : 400,
                  fontSize: '0.78rem',
                  cursor: 'pointer',
                  transition: 'all 0.15s',
                }}
              >
                {icon}{f.label}
                <span style={{
                  marginLeft: '0.4rem',
                  background: active ? `${col}33` : 'rgba(255,255,255,0.06)',
                  color: active ? col : 'var(--text-muted)',
                  borderRadius: '99px',
                  padding: '0 0.4rem',
                  fontSize: '0.7rem',
                  fontWeight: 700,
                }}>{counts[f.key] ?? 0}</span>
              </button>
            )
          })}
        </div>

        <div className="card" style={{ marginBottom: '1.5rem', padding: 0, overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.85rem' }}>
            <thead>
              <tr style={{ background: 'var(--surface)', borderBottom: '1px solid var(--border)' }}>
                {['Rank', 'Verdict', 'Threat Score', 'High', 'Med', 'Low', 'CSV Row', ''].map(h => (
                  <th key={h} style={{ padding: '0.65rem 1rem', textAlign: 'left', color: 'var(--text-dim)', fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {visible.map((r, i) => {
                const threatPct = parseFloat((r.probability * 100).toFixed(1))
                const col       = BAND_COLOR[r.band]
                const dim       = BAND_DIM[r.band]
                return (
                  <tr
                    key={i}
                    onClick={() => handleRowClick(r)}
                    style={{ borderBottom: '1px solid var(--border)', cursor: 'pointer', transition: 'background 0.15s' }}
                    onMouseEnter={e => e.currentTarget.style.background = 'var(--surface)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontWeight: 700 }}>#{r.rank}</td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{
                        display: 'inline-block',
                        padding: '0.2rem 0.6rem',
                        borderRadius: '4px',
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        background: dim,
                        color: col,
                      }}>
                        {BAND_ICON[r.band]} {r.band.toUpperCase()}
                      </span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{ color: col, fontWeight: 600 }}>{threatPct}%</span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--danger)' }}>{r.high_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--warning)' }}>{r.medium_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)' }}>{r.low_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)', fontSize: '0.75rem' }}>{r.row_index}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontSize: '0.75rem', whiteSpace: 'nowrap' }}>
                      View →
                    </td>
                  </tr>
                )
              })}
              {visible.length === 0 && (
                <tr>
                  <td colSpan={8} style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                    No {filter} records found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* ── Load More footer ── */}
        {hasMore && (
          <div style={{ textAlign: 'center', padding: '0.75rem 0 1.5rem' }}>
            <button
              className="btn btn-secondary"
              onClick={() => setPageSize(p => p + 200)}
            >
              Load 200 more &mdash; {filtered.length - pageSize} remaining
            </button>
          </div>
        )}
        {!hasMore && annotated.length > 200 && (
          <p style={{ textAlign: 'center', fontSize: '0.78rem', color: 'var(--text-muted)', padding: '0.5rem 0 1.5rem' }}>
            All {annotated.length.toLocaleString()} records displayed.
          </p>
        )}
      </div>
    )
  }

  // ── Single result mode ────────────────────────────────────────────────────
  return <SingleResult result={result} onBack={() => navigate('/')} />
}
